"""Verify the panel events generated by scripted encoder turns."""

import unittest
from unittest.mock import Mock, call

from emu import panelin
from emu.session import Session


class EncoderCadenceTests(unittest.TestCase):
    def setUp(self):
        self.session = Session.__new__(Session)
        self.session.device = Mock(encoder_counts=4)
        self.session.device.encoder_channel.return_value = 0
        self.session.model_panel = None
        self.session.ms = 0
        self.session.inputs = []
        self.events = Mock()
        self.session._feed = self.events.feed
        self.session.run_ms = self.events.wait

    def test_multiple_detents_follow_panel_cadence(self):
        for direction in (1, -1):
            with self.subTest(direction=direction):
                self.events.reset_mock()
                self.session.turn(1, direction * 3, after_ms=99)
                event = call.feed(
                    panelin.encode_encoder(0, direction * 4),
                    'turn 1 %+d' % (direction * 4),
                )
                self.assertEqual(self.events.mock_calls, [
                    event, call.wait(40), event, call.wait(40), event, call.wait(99),
                ])

    def test_zero_detents_only_waits(self):
        self.session.turn(1, 0, after_ms=25)
        self.assertEqual(self.events.mock_calls, [call.wait(25)])

    def test_model_panel_receives_aggregated_counts(self):
        self.session.model_panel = Mock()
        self.session.turn(1, 3, after_ms=99)
        self.session.model_panel.turn.assert_called_once_with(0, 12)
        self.assertEqual(self.events.mock_calls, [call.wait(99)])
